fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since the array has at least one element, we can safely compare adjacent pairs.
    for i in 1..arr.len() {
        if arr[i - 1] > arr[i] {
            return false;
        }
    }
    true
}

